E=W['W_E'];P=W['W_pos'];WU=W['W_U']
Q0=W['L0.W_Q'][0];K0=W['L0.W_K'][0];VO0=W['L0.W_V'][0]@W['L0.W_O'][0]
Q1=W['L1.W_Q'][0];K1=W['L1.W_K'][0];VO1=W['L1.W_V'][0]@W['L1.W_O'][0]
M0=Q0@K0.T/np.sqrt(3); M1=Q1@K1.T/np.sqrt(3)
y=run(X).argmax(1)
def sm(z):
    z=z-z.max(-1,keepdims=True); e=np.exp(z); return e/e.sum(-1,keepdims=True)
def F(Em=E,Pm=P,M0m=M0,VO0m=VO0,M1m=M1,VO1m=VO1,WUm=WU):
    h=Em[X]+Pm[None]
    out={}
    for M,VO in ((M0m,VO0m),(M1m,VO1m)):
        s=h@M@h.transpose(0,2,1)
        p_=sm(s)
        h=h+p_@h@VO
    return h[:,3,:]@WUm
